import numpy as np

def feature_point(x, parameters):
    width = int(parameters.get('width', 8))
    decay = float(parameters.get('decay', 0.7))
    state = np.zeros(width)
    for j in range(width):
        state[j] = np.sum(np.tanh((j + 1) * x))
        if j:
            state[j] += decay * state[j - 1]
    return state / np.sqrt(width)
